89. /// A thin wrapper around a Hyper Server object that exposes some interfaces that
90. /// we find useful.
91. pub struct HttpServerStarter<C: ServerContext> {
92.     app_state: Arc<DropshotState<C>>,
93.     local_addr: SocketAddr,
94.     wrapped: WrappedHttpServerStarter<C>,
95. }
