97. impl<C: ServerContext> HttpServerStarter<C> {
98.     pub fn new(
99.         config: &ConfigDropshot,
100.         api: ApiDescription<C>,
101.         private: C,
102.         log: &Logger,
103.     ) -> Result<HttpServerStarter<C>, GenericError> {
104.         let server_config = ServerConfig {
105.             // We start aggressively to ensure test coverage.
106.             request_body_max_bytes: config.request_body_max_bytes,
107.             page_max_nitems: NonZeroU32::new(10000).unwrap(),
108.             page_default_nitems: NonZeroU32::new(100).unwrap(),
109.         };
110. 
111.         let starter = match config.tls {
112.             Some(_) => {
113.                 let (starter, app_state, local_addr) =
114.                     InnerHttpsServerStarter::new(
115.                         config,
116.                         server_config,
117.                         api,
118.                         private,
119.                         log,
120.                     )?;
121.                 HttpServerStarter {
122.                     app_state,
123.                     local_addr,
124.                     wrapped: WrappedHttpServerStarter::Https(starter),
125.                 }
126.             }
127.             None => {
128.                 let (starter, app_state, local_addr) =
129.                     InnerHttpServerStarter::new(
130.                         config,
131.                         server_config,
132.                         api,
133.                         private,
134.                         log,
135.                     )?;
136.                 HttpServerStarter {
137.                     app_state,
138.                     local_addr,
139.                     wrapped: WrappedHttpServerStarter::Http(starter),
140.                 }
141.             }
142.         };
143. 
144.         for (path, method, _) in &starter.app_state.router {
145.             debug!(starter.app_state.log, "registered endpoint";
146.                 "method" => &method,
147.                 "path" => &path
148.             );
149.         }
150. 
151.         Ok(starter)
152.     }
153. 
154.     pub fn start(self) -> HttpServer<C> {
155.         let (tx, rx) = tokio::sync::oneshot::channel::<()>();
156.         let log_close = self.app_state.log.new(o!());
157.         let join_handle = match self.wrapped {
158.             WrappedHttpServerStarter::Http(http) => http.start(rx, log_close),
159.             WrappedHttpServerStarter::Https(https) => {
160.                 https.start(rx, log_close)
161.             }
162.         }
163.         .map(|r| {
164.             r.map_err(|e| format!("waiting for server: {e}"))?
165.                 .map_err(|e| format!("server stopped: {e}"))
166.         });
167.         info!(self.app_state.log, "listening");
168. 
169.         #[cfg(feature = "usdt-probes")]
170.         let probe_registration = match usdt::register_probes() {
171.             Ok(_) => {
172.                 debug!(
173.                     self.app_state.log,
174.                     "successfully registered DTrace USDT probes"
175.                 );
176.                 ProbeRegistration::Succeeded
177.             }
178.             Err(e) => {
179.                 let msg = e.to_string();
180.                 error!(
181.                     self.app_state.log,
182.                     "failed to register DTrace USDT probes: {}", msg
183.                 );
184.                 ProbeRegistration::Failed(msg)
185.             }
186.         };
187.         #[cfg(not(feature = "usdt-probes"))]
188.         let probe_registration = {
189.             debug!(
190.                 self.app_state.log,
191.                 "DTrace USDT probes compiled out, not registering"
192.             );
193.             ProbeRegistration::Disabled
194.         };
195. 
196.         HttpServer {
197.             probe_registration,
198.             app_state: self.app_state,
199.             local_addr: self.local_addr,
200.             closer: CloseHandle { close_channel: Some(tx) },
201.             join_future: join_handle.boxed().shared(),
202.         }
203.     }
204. }
