218. impl<C: ServerContext> InnerHttpServerStarter<C> {
219.     /// Begins execution of the underlying Http server.
220.     fn start(
221.         self,
222.         close_signal: tokio::sync::oneshot::Receiver<()>,
223.         log_close: Logger,
224.     ) -> tokio::task::JoinHandle<Result<(), hyper::Error>> {
225.         let graceful = self.0.with_graceful_shutdown(async move {
226.             close_signal.await.expect(
227.                 "dropshot server shutting down without invoking close()",
228.             );
229.             info!(log_close, "received request to begin graceful shutdown");
230.         });
231. 
232.         tokio::spawn(async { graceful.await })
233.     }
