235.     /// Set up an HTTP server bound on the specified address that runs registered
236.     /// handlers.  You must invoke `start()` on the returned instance of
237.     /// `HttpServerStarter` (and await the result) to actually start the server.
238.     ///
239.     /// TODO-cleanup We should be able to take a reference to the ApiDescription.
240.     /// We currently can't because we need to hang onto the router.
241.     fn new(
242.         config: &ConfigDropshot,
243.         server_config: ServerConfig,
244.         api: ApiDescription<C>,
245.         private: C,
246.         log: &Logger,
247.     ) -> Result<InnerHttpServerStarterNewReturn<C>, hyper::Error> {
248.         let incoming = AddrIncoming::bind(&config.bind_address)?;
249.         let local_addr = incoming.local_addr();
250. 
251.         // TODO-cleanup too many Arcs?
252.         let app_state = Arc::new(DropshotState {
253.             private,
254.             config: server_config,
255.             router: api.into_router(),
256.             log: log.new(o!("local_addr" => local_addr)),
257.             local_addr,
258.             tls_acceptor: None,
259.         });
260. 
261.         let make_service = ServerConnectionHandler::new(app_state.clone());
262.         let builder = hyper::Server::builder(incoming);
263.         let server = builder.serve(make_service);
264.         Ok((InnerHttpServerStarter(server), app_state, local_addr))
265.     }
266. }
