418. impl hyper::server::accept::Accept for HttpsAcceptor {
419.     type Conn = TlsConn;
420.     type Error = std::io::Error;
421. 
422.     fn poll_accept(
423.         mut self: Pin<&mut Self>,
424.         ctx: &mut core::task::Context,
425.     ) -> core::task::Poll<Option<Result<Self::Conn, Self::Error>>> {
426.         let pinned = Pin::new(&mut self.stream);
427.         pinned.poll_next(ctx)
428.     }
429. }
