435. /// Create a TLS configuration from the Dropshot config structure.
436. // Eventually we may want to change the APIs to allow users to pass
437. // a rustls::ServerConfig themselves
438. impl TryFrom<&ConfigTls> for rustls::ServerConfig {
439.     type Error = std::io::Error;
440. 
441.     fn try_from(config: &ConfigTls) -> std::io::Result<Self> {
442.         let certs = load_certs(&config)?;
443.         let private_key = load_private_key(&config)?;
444.         let mut cfg = rustls::ServerConfig::builder()
445.             // TODO: We may want to expose protocol configuration in our
446.             // config
447.             .with_safe_default_cipher_suites()
448.             .with_safe_default_kx_groups()
449.             .with_safe_default_protocol_versions()
450.             .unwrap()
451.             .with_client_cert_verifier(rustls::server::NoClientAuth::new())
452.             .with_single_cert(certs, private_key)
453.             .expect("bad certificate/key");
454.         cfg.alpn_protocols = vec![b"h2".to_vec(), b"http/1.1".to_vec()];
455.         Ok(cfg)
456.     }
457. }
