462. impl<C: ServerContext> InnerHttpsServerStarter<C> {
463.     /// Begins execution of the underlying Http server.
464.     fn start(
465.         self,
466.         close_signal: tokio::sync::oneshot::Receiver<()>,
467.         log_close: Logger,
468.     ) -> tokio::task::JoinHandle<Result<(), hyper::Error>> {
469.         let graceful = self.0.with_graceful_shutdown(async move {
470.             close_signal.await.expect(
471.                 "dropshot server shutting down without invoking close()",
472.             );
473.             info!(log_close, "received request to begin graceful shutdown");
474.         });
475. 
476.         tokio::spawn(async { graceful.await })
477.     }
478. 
479.     fn new(
480.         config: &ConfigDropshot,
481.         server_config: ServerConfig,
482.         api: ApiDescription<C>,
483.         private: C,
484.         log: &Logger,
485.     ) -> Result<InnerHttpsServerStarterNewReturn<C>, GenericError> {
486.         let acceptor = Arc::new(Mutex::new(TlsAcceptor::from(Arc::new(
487.             // Unwrap is safe here because we cannot enter this code path
488.             // without a TLS configuration
489.             rustls::ServerConfig::try_from(config.tls.as_ref().unwrap())?,
490.         ))));
491. 
492.         let tcp = {
493.             let listener = std::net::TcpListener::bind(&config.bind_address)?;
494.             listener.set_nonblocking(true)?;
495.             // We use `from_std` instead of just calling `bind` here directly
496.             // to avoid invoking an async function, to match the interface
497.             // provided by `HttpServerStarter::new`.
498.             TcpListener::from_std(listener)?
499.         };
500. 
501.         let local_addr = tcp.local_addr()?;
502.         let logger = log.new(o!("local_addr" => local_addr));
503.         let https_acceptor =
504.             HttpsAcceptor::new(logger.clone(), acceptor.clone(), tcp);
505. 
506.         let app_state = Arc::new(DropshotState {
507.             private,
508.             config: server_config,
509.             router: api.into_router(),
510.             log: logger,
511.             local_addr,
512.             tls_acceptor: Some(acceptor),
513.         });
514. 
515.         let make_service = ServerConnectionHandler::new(Arc::clone(&app_state));
516.         let server = Server::builder(https_acceptor).serve(make_service);
517. 
518.         Ok((InnerHttpsServerStarter(server), app_state, local_addr))
519.     }
520. }
