522. impl<C: ServerContext> Service<&TlsConn> for ServerConnectionHandler<C> {
523.     type Response = ServerRequestHandler<C>;
524.     type Error = GenericError;
525.     type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;
