527.     fn poll_ready(
528.         &mut self,
529.         _ctx: &mut Context<'_>,
530.     ) -> Poll<Result<(), Self::Error>> {
531.         Poll::Ready(Ok(()))
532.     }
533. 
534.     fn call(&mut self, conn: &TlsConn) -> Self::Future {
535.         let server = Arc::clone(&self.server);
536.         let remote_addr = conn.remote_addr();
537.         Box::pin(http_connection_handle(server, remote_addr))
538.     }
539. }
