543. /// Future returned by [`Server::wait_for_shutdown()`].
544. pub struct ShutdownWaitFuture(SharedBoxFuture<Result<(), String>>);
545. 
546. impl Future for ShutdownWaitFuture {
547.     type Output = Result<(), String>;
548. 
549.     fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
550.         Pin::new(&mut self.get_mut().0).poll(cx)
551.     }
552. }
553. 
554. impl FusedFuture for ShutdownWaitFuture {
555.     fn is_terminated(&self) -> bool {
556.         self.0.is_terminated()
557.     }
558. }
