560. /// A running Dropshot HTTP server.
561. ///
562. /// The generic traits represent the following:
563. /// - C: Caller-supplied server context
564. pub struct HttpServer<C: ServerContext> {
565.     probe_registration: ProbeRegistration,
566.     app_state: Arc<DropshotState<C>>,
567.     local_addr: SocketAddr,
568.     closer: CloseHandle,
569.     join_future: SharedBoxFuture<Result<(), String>>,
570. }
571. 
572. // Handle used to trigger the shutdown of an [HttpServer].
573. struct CloseHandle {
574.     close_channel: Option<tokio::sync::oneshot::Sender<()>>,
575. }
576. 
577. impl<C: ServerContext> HttpServer<C> {
578.     pub fn local_addr(&self) -> SocketAddr {
579.         self.local_addr
580.     }
581. 
582.     pub fn app_private(&self) -> &C {
583.         &self.app_state.private
584.     }
585. 
586.     pub fn using_tls(&self) -> bool {
587.         self.app_state.using_tls()
588.     }
589. 
590.     /// Update TLS certificates for a running HTTPS server.
591.     pub async fn refresh_tls(&self, config: &ConfigTls) -> Result<(), String> {
592.         let acceptor = &self
593.             .app_state
594.             .tls_acceptor
595.             .as_ref()
596.             .ok_or_else(|| "Not configured for TLS".to_string())?;
597. 
598.         *acceptor.lock().await = TlsAcceptor::from(Arc::new(
599.             rustls::ServerConfig::try_from(config).unwrap(),
600.         ));
601.         Ok(())
602.     }
603. 
604.     /// Return the result of registering the server's DTrace USDT probes.
605.     ///
606.     /// See [`ProbeRegistration`] for details.
607.     pub fn probe_registration(&self) -> &ProbeRegistration {
608.         &self.probe_registration
609.     }
610. 
611.     /// Returns a future which completes when the server has shut down.
612.     ///
613.     /// This function does not cause the server to shut down. It just waits for
614.     /// the shutdown to happen.
615.     ///
616.     /// To trigger a shutdown, Call [HttpServer::close] (which also awaits shutdown).
617.     pub fn wait_for_shutdown(&self) -> ShutdownWaitFuture {
618.         ShutdownWaitFuture(self.join_future.clone())
619.     }
620. 
621.     /// Signals the currently running server to stop and waits for it to exit.
622.     pub async fn close(mut self) -> Result<(), String> {
623.         self.closer
624.             .close_channel
625.             .take()
626.             .expect("cannot close twice")
627.             .send(())
628.             .expect("failed to send close signal");
629.         self.join_future.await
630.     }
631. }
632. 
633. // For graceful termination, the `close()` function is preferred, as it can
634. // report errors and wait for termination to complete.  However, we impl
635. // `Drop` to attempt to shut down the server to handle less clean shutdowns
636. // (e.g., from failing tests).
637. impl Drop for CloseHandle {
638.     fn drop(&mut self) {
639.         if let Some(c) = self.close_channel.take() {
640.             c.send(()).expect("failed to send close signal")
641.         }
642.     }
643. }
644. 
645. impl<C: ServerContext> Future for HttpServer<C> {
646.     type Output = Result<(), String>;
647. 
648.     fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
649.         let server = Pin::into_inner(self);
650.         let join_future = Pin::new(&mut server.join_future);
651.         join_future.poll(cx)
652.     }
653. }
654. 
655. impl<C: ServerContext> FusedFuture for HttpServer<C> {
656.     fn is_terminated(&self) -> bool {
657.         self.join_future.is_terminated()
658.     }
659. }
660. 
661. /// Initial entry point for handling a new connection to the HTTP server.
662. /// This is invoked by Hyper when a new connection is accepted.  This function
663. /// must return a Hyper Service object that will handle requests for this
664. /// connection.
665. async fn http_connection_handle<C: ServerContext>(
666.     server: Arc<DropshotState<C>>,
667.     remote_addr: SocketAddr,
668. ) -> Result<ServerRequestHandler<C>, GenericError> {
669.     info!(server.log, "accepted connection"; "remote_addr" => %remote_addr);
670.     Ok(ServerRequestHandler::new(server, remote_addr))
671. }
672. 
673. /// Initial entry point for handling a new request to the HTTP server.  This is
674. /// invoked by Hyper when a new request is received.  This function returns a
675. /// Result that either represents a valid HTTP response or an error (which will
676. /// also get turned into an HTTP response).
677. async fn http_request_handle_wrap<C: ServerContext>(
678.     server: Arc<DropshotState<C>>,
679.     remote_addr: SocketAddr,
680.     request: Request<Body>,
681. ) -> Result<Response<Body>, GenericError> {
682.     // This extra level of indirection makes error handling much more
683.     // straightforward, since the request handling code can simply return early
684.     // with an error and we'll treat it like an error from any of the endpoints
685.     // themselves.
686.     let request_id = generate_request_id();
687.     let request_log = server.log.new(o!(
688.         "remote_addr" => remote_addr,
689.         "req_id" => request_id.clone(),
690.         "method" => request.method().as_str().to_string(),
691.         "uri" => format!("{}", request.uri()),
692.     ));
693.     trace!(request_log, "incoming request");
694.     #[cfg(feature = "usdt-probes")]
695.     probes::request__start!(|| {
696.         let uri = request.uri();
697.         crate::dtrace::RequestInfo {
698.             id: request_id.clone(),
699.             local_addr: server.local_addr,
700.             remote_addr,
701.             method: request.method().to_string(),
702.             path: uri.path().to_string(),
703.             query: uri.query().map(|x| x.to_string()),
704.         }
705.     });
706. 
707.     // Copy local address to report later during the finish probe, as the
708.     // server is passed by value to the request handler function.
709.     #[cfg(feature = "usdt-probes")]
710.     let local_addr = server.local_addr;
711. 
712.     let maybe_response = http_request_handle(
713.         server,
714.         request,
715.         &request_id,
716.         request_log.new(o!()),
717.     )
718.     .await;
719. 
720.     let response = match maybe_response {
721.         Err(error) => {
722.             let message_external = error.external_message.clone();
723.             let message_internal = error.internal_message.clone();
724.             let r = error.into_response(&request_id);
725. 
726.             #[cfg(feature = "usdt-probes")]
727.             probes::request__done!(|| {
728.                 crate::dtrace::ResponseInfo {
729.                     id: request_id.clone(),
730.                     local_addr,
731.                     remote_addr,
732.                     status_code: r.status().as_u16(),
733.                     message: message_external.clone(),
734.                 }
735.             });
736. 
737.             // TODO-debug: add request and response headers here
738.             info!(request_log, "request completed";
739.                 "response_code" => r.status().as_str().to_string(),
740.                 "error_message_internal" => message_internal,
741.                 "error_message_external" => message_external,
742.             );
743. 
744.             r
745.         }
746. 
747.         Ok(response) => {
748.             // TODO-debug: add request and response headers here
749.             info!(request_log, "request completed";
750.                 "response_code" => response.status().as_str().to_string()
751.             );
752. 
753.             #[cfg(feature = "usdt-probes")]
754.             probes::request__done!(|| {
755.                 crate::dtrace::ResponseInfo {
756.                     id: request_id.parse().unwrap(),
757.                     local_addr,
758.                     remote_addr,
759.                     status_code: response.status().as_u16(),
760.                     message: "".to_string(),
761.                 }
762.             });
763. 
764.             response
765.         }
766.     };
767. 
768.     Ok(response)
769. }
770. 
771. async fn http_request_handle<C: ServerContext>(
772.     server: Arc<DropshotState<C>>,
773.     request: Request<Body>,
774.     request_id: &str,
775.     request_log: Logger,
776. ) -> Result<Response<Body>, HttpError> {
777.     // TODO-hardening: is it correct to (and do we correctly) read the entire
778.     // request body even if we decide it's too large and are going to send a 400
779.     // response?
780.     // TODO-hardening: add a request read timeout as well so that we don't allow
781.     // this to take forever.
782.     // TODO-correctness: Do we need to dump the body on errors?
783.     let method = request.method();
784.     let uri = request.uri();
785.     let lookup_result =
786.         server.router.lookup_route(&method, uri.path().into())?;
787.     let rqctx = RequestContext {
788.         server: Arc::clone(&server),
789.         request: RequestInfo::from(&request),
790.         path_variables: lookup_result.variables,
791.         body_content_type: lookup_result.body_content_type,
792.         request_id: request_id.to_string(),
793.         log: request_log,
794.     };
795.     let mut response =
796.         lookup_result.handler.handle_request(rqctx, request).await?;
797.     response.headers_mut().insert(
798.         HEADER_REQUEST_ID,
799.         http::header::HeaderValue::from_str(&request_id).unwrap(),
800.     );
801.     Ok(response)
802. }
