804. // This function should probably be parametrized by some name of the service
805. // that is expected to be unique within an organization.  That way, it would be
806. // possible to determine from a given request id which service it was from.
807. // TODO should we encode more information here?  Service?  Instance?  Time up to
808. // the hour?
809. fn generate_request_id() -> String {
810.     format!("{}", Uuid::new_v4())
811. }
