813. /// ServerConnectionHandler is a Hyper Service implementation that forwards
814. /// incoming connections to `http_connection_handle()`, providing the server
815. /// state object as an additional argument.  We could use `make_service_fn` here
816. /// using a closure to capture the state object, but the resulting code is a bit
817. /// simpler without it.
818. pub struct ServerConnectionHandler<C: ServerContext> {
819.     /// backend state that will be made available to the connection handler
820.     server: Arc<DropshotState<C>>,
821. }
822. 
823. impl<C: ServerContext> ServerConnectionHandler<C> {
824.     /// Create an ServerConnectionHandler with the given state object that
825.     /// will be made available to the handler.
826.     fn new(server: Arc<DropshotState<C>>) -> Self {
827.         ServerConnectionHandler { server }
828.     }
829. }
830. 
831. impl<T: ServerContext> Service<&AddrStream> for ServerConnectionHandler<T> {
832.     // Recall that a Service in this context is just something that takes a
833.     // request (which could be anything) and produces a response (which could be
834.     // anything).  This being a connection handler, the request type is an
835.     // AddrStream (which wraps a TCP connection) and the response type is
836.     // another Service: one that accepts HTTP requests and produces HTTP
837.     // responses.
838.     type Response = ServerRequestHandler<T>;
839.     type Error = GenericError;
840.     type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;
841. 
842.     fn poll_ready(
843.         &mut self,
844.         _cx: &mut Context<'_>,
845.     ) -> Poll<Result<(), Self::Error>> {
846.         // TODO is this right?
847.         Poll::Ready(Ok(()))
848.     }
849. 
850.     fn call(&mut self, conn: &AddrStream) -> Self::Future {
851.         // We're given a borrowed reference to the AddrStream, but our interface
852.         // is async (which is good, so that we can support time-consuming
853.         // operations as part of receiving requests).  To avoid having to ensure
854.         // that conn's lifetime exceeds that of this async operation, we simply
855.         // copy the only useful information out of the conn: the SocketAddr.  We
856.         // may want to create our own connection type to encapsulate the socket
857.         // address and any other per-connection state that we want to keep.
858.         let server = Arc::clone(&self.server);
859.         let remote_addr = conn.remote_addr();
860.         Box::pin(http_connection_handle(server, remote_addr))
861.     }
862. }
863. 
864. /// ServerRequestHandler is a Hyper Service implementation that forwards
865. /// incoming requests to `http_request_handle_wrap()`, including as an argument
866. /// the backend server state object.  We could use `service_fn` here using a
867. /// closure to capture the server state object, but the resulting code is a bit
868. /// simpler without all that.
869. pub struct ServerRequestHandler<C: ServerContext> {
870.     /// backend state that will be made available to the request handler
871.     server: Arc<DropshotState<C>>,
872.     remote_addr: SocketAddr,
873. }
874. 
875. impl<C: ServerContext> ServerRequestHandler<C> {
876.     /// Create a ServerRequestHandler object with the given state object that
877.     /// will be provided to the handler function.
878.     fn new(server: Arc<DropshotState<C>>, remote_addr: SocketAddr) -> Self {
879.         ServerRequestHandler { server, remote_addr }
880.     }
881. }
882. 
883. impl<C: ServerContext> Service<Request<Body>> for ServerRequestHandler<C> {
884.     type Response = Response<Body>;
885.     type Error = GenericError;
886.     type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;
887. 
888.     fn poll_ready(
889.         &mut self,
890.         _cx: &mut Context<'_>,
891.     ) -> Poll<Result<(), Self::Error>> {
892.         // TODO is this right?
893.         Poll::Ready(Ok(()))
894.     }
895. 
896.     fn call(&mut self, req: Request<Body>) -> Self::Future {
897.         Box::pin(http_request_handle_wrap(
898.             Arc::clone(&self.server),
899.             self.remote_addr,
900.             req,
901.         ))
902.     }
903. }
